import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"ADR-004 — Spring Cloud Gateway Perimeter, RS256 Auth & Zero-Trust Re-Verification","description":"","frontmatter":{},"headers":[],"relativePath":"adr/adr-004-spring-cloud-gateway.md","filePath":"adr/adr-004-spring-cloud-gateway.md"}'),n={name:"adr/adr-004-spring-cloud-gateway.md"};function i(r,e,c,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="adr-004-—-spring-cloud-gateway-perimeter-rs256-auth-zero-trust-re-verification" tabindex="-1">ADR-004 — Spring Cloud Gateway Perimeter, RS256 Auth &amp; Zero-Trust Re-Verification <a class="header-anchor" href="#adr-004-—-spring-cloud-gateway-perimeter-rs256-auth-zero-trust-re-verification" aria-label="Permalink to &quot;ADR-004 — Spring Cloud Gateway Perimeter, RS256 Auth &amp; Zero-Trust Re-Verification&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← ADR Index</a> · <a href="./../api/rs256-jwt-flow.html">RS256 JWT Flow</a> · <a href="./../api/redis-rate-limiting-filter.html">Redis Rate Limiting</a> · <a href="/brandhub-infrastructure/view.html?file=architecture/architecture.html">Architecture Diagram</a></p><ul><li><strong>Status:</strong> Accepted</li><li><strong>Owners:</strong> Platform Security &amp; Core Backend Leads</li><li><strong>Related Docs:</strong> <a href="./../api/api-response-format.html">API Response Format</a> · <a href="./../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a> · <a href="./../operations/wake-on-request.html">Wake-on-Request Runbook</a></li></ul><hr><h2 id="_1-context-problem-statement" tabindex="-1">1. Context &amp; Problem Statement <a class="header-anchor" href="#_1-context-problem-statement" aria-label="Permalink to &quot;1. Context &amp; Problem Statement&quot;">​</a></h2><p><code>brandhub-web</code> (<code>https://brandhub.id.vn</code>) and <code>brandhub-mobile-app</code> interact with REST endpoints, multipart S3/Repository streams, public guest links (surveys, package shares, mail unsubscribe), third-party webhooks (SePay VietQR, Meta/TikTok/Threads OAuth callbacks), and dual STOMP WebSockets (<code>/ws/chat</code>, <code>/ws/tasks</code>).</p><p>Exposing <code>brandhub-business-service</code> (<code>:8081</code>), <code>brandhub-ai-service</code> (<code>:8082</code>), and <code>brandhub-publisher-service</code> (<code>:8083</code>) directly to the public internet would duplicate CORS, rate-limiting, request-correlation, and token-revocation logic across Java and Python stacks while widening the attack surface of internal <code>X-Internal-Key</code> routes. At the same time, pushing BrandHub&#39;s complex 2-tier authorization rules (<code>agencies.owner_id</code> + per-workspace <code>Manager</code>/<code>Creator</code>/<code>Client</code> membership) into an edge gateway would turn the gateway into a stateful monolith coupled to PostgreSQL.</p><hr><h2 id="_2-evaluated-options" tabindex="-1">2. Evaluated Options <a class="header-anchor" href="#_2-evaluated-options" aria-label="Permalink to &quot;2. Evaluated Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Option</th><th style="text-align:left;">Pros</th><th style="text-align:left;">Cons / Why Rejected or Selected</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Option A: Nginx Reverse Proxy Only</strong> (All JWT, rate-limit &amp; header logic inside each microservice)</td><td style="text-align:left;">Minimal memory overhead on <code>gateway</code> EC2</td><td style="text-align:left;">Cannot run shared reactive Redis Lua rate limiters + <code>jwt:blacklist:{jti}</code> checks + unified <code>ApiResponse&lt;T&gt;</code> JSON error serialization without OpenResty/Lua custom plugins</td></tr><tr><td style="text-align:left;"><strong>Option B: Kong / Envoy API Gateway</strong></td><td style="text-align:left;">High throughput C/Go proxy</td><td style="text-align:left;">Introduces a separate declarative plugin stack outside the team&#39;s Java 21 / Spring Boot 3 skillset and requires custom plugins for BrandHub&#39;s capability-IP rate limiters</td></tr><tr><td style="text-align:left;"><strong>Option C: Spring Cloud Gateway (WebFlux / Netty) Behind Nginx TLS</strong> <em>(Selected)</em></td><td style="text-align:left;">Non-blocking Netty event loop fits inside <code>640m</code> RAM on <code>t3.small</code>; shares Java 21 + <code>ApiResponse&lt;T&gt;</code> error contracts; clean custom <code>WebFilter</code> &amp; <code>GatewayFilterFactory</code> pipeline</td><td style="text-align:left;">Static route table in <code>application.yml</code> (acceptable for a fixed 4-service backend)</td></tr></tbody></table><hr><h2 id="_3-decision-architecture-defense-in-depth-perimeter" tabindex="-1">3. Decision Architecture (Defense-in-Depth Perimeter) <a class="header-anchor" href="#_3-decision-architecture-defense-in-depth-perimeter" aria-label="Permalink to &quot;3. Decision Architecture (Defense-in-Depth Perimeter)&quot;">​</a></h2><p>Deploy <strong>Spring Cloud Gateway</strong> (<code>brandhub-api-gateway</code> on <code>:8080</code> behind Nginx <code>:80</code>/<code>:443</code> on <code>brandhub-api-gateway</code> EC2 <code>172.31.27.199</code>) as the sole public API ingress, paired with <strong>asymmetric RS256 JWT verification</strong> and <strong>downstream Zero-Trust re-verification</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Internet Client ──HTTPS──► Nginx (:443, TLS 1.2/1.3, /edit-video/ -&gt; 172.31.20.80:8095 + @wake_edit_video)</span></span>
<span class="line"><span>                             │</span></span>
<span class="line"><span>                             ▼</span></span>
<span class="line"><span>                   brandhub-api-gateway (:8080, Netty WebFlux)</span></span>
<span class="line"><span>                     ├─ 1. RequestIdWebFilter (HIGHEST_PRECEDENCE): validates or generates X-Request-Id</span></span>
<span class="line"><span>                     ├─ 2. InboundSecurityWebFilter (HIGHEST_PRECEDENCE + 1):</span></span>
<span class="line"><span>                     │      • Rejects path smuggling (; , .. , \\, %2e%2e, %3b, %00) -&gt; 400 INVALID_REQUEST_PATH</span></span>
<span class="line"><span>                     │      • Blocks external access to /api/v1/internal/**, /api/v1/test/** -&gt; 403 FORBIDDEN</span></span>
<span class="line"><span>                     │      • Strips spoofed inbound X-User-Id, X-User-Role, X-Workspace-Id, X-Internal-Key</span></span>
<span class="line"><span>                     │      • Attaches nosniff, X-Frame-Options: DENY, Referrer-Policy, Permissions-Policy</span></span>
<span class="line"><span>                     ├─ 3. Route Predicates &amp; JwtAuthFilterGatewayFilterFactory:</span></span>
<span class="line"><span>                     │      • Verifies RS256 signature using ONLY JWT_PUBLIC_KEY (cannot mint tokens)</span></span>
<span class="line"><span>                     │      • Rejects 2FA challenge tokens (&quot;type&quot; claim) &amp; refresh tokens (missing &quot;role&quot;)</span></span>
<span class="line"><span>                     │      • Checks reactive Redis key jwt:blacklist:{jti}</span></span>
<span class="line"><span>                     │      • Injects verified X-User-Id, X-User-Role, X-Workspace-Id trace headers</span></span>
<span class="line"><span>                     ├─ 4. RateLimitGatewayFilterFactory:</span></span>
<span class="line"><span>                     │      • Atomic Lua INCR + EXPIRE on ratelimit:gateway:{userId|ip}:{minute}</span></span>
<span class="line"><span>                     └─ 5. Forwards to VPC-private business-service (:8081) or publisher OAuth (:8083)</span></span>
<span class="line"><span>                             │</span></span>
<span class="line"><span>                             ▼</span></span>
<span class="line"><span>                   brandhub-business-service (:8081)</span></span>
<span class="line"><span>                     └─ JwtAuthenticationFilter independently re-verifies Authorization: Bearer &lt;jwt&gt;</span></span>
<span class="line"><span>                        and resolves live 2-tier RBAC (Admin / Owner / Manager / Creator / Client) from PostgreSQL</span></span></code></pre></div><hr><h2 id="_4-real-codebase-route-grounding" tabindex="-1">4. Real Codebase &amp; Route Grounding <a class="header-anchor" href="#_4-real-codebase-route-grounding" aria-label="Permalink to &quot;4. Real Codebase &amp; Route Grounding&quot;">​</a></h2><ul><li><strong>Gateway Route Classes (<code>brandhub-api-gateway/src/main/resources/application.yml</code>)</strong>: <ul><li><strong>Authenticated API routes (<code>/api/v1/**</code>, <code>/api/monitoring/enrollments</code>, <code>/api/monitoring/servers</code>)</strong>: Protected by <code>JwtAuthFilter</code> + per-user <code>RateLimit</code> (<code>100</code> req/min default; stricter quotas for AI text/image/video and publishing).</li><li><strong>Public <code>Guest</code> &amp; Webhook routes</strong>: <code>/api/v1/auth/**</code> (login, register, refresh, Google OAuth), <code>/api/v1/public/{mail,surveys,billing/plans,media-packages}/**</code> (IP-scoped <code>RateLimit</code>), <code>POST /api/v1/billing/webhooks/sepay</code> (verified by SePay API key/signature inside <code>BillingController</code>), and <code>GET /api/v1/social/{facebook,instagram,tiktok,threads}/{authorize,callback}</code> (routed to <code>publisher-service:8083</code> with single-use 60s connect tickets + <code>bh_oauth_state</code> cookie).</li><li><strong>STOMP WebSocket Upgrades (<code>/ws/chat/**</code>, <code>/ws/tasks/**</code>)</strong>: Proxied over <code>ws://</code> to <code>business-service:8081</code>, where <code>WsJwtHandshakeInterceptor</code> and <code>ChatInboundChannelInterceptor</code> authenticate the handshake/CONNECT frame (<code>16 KB</code> frame cap).</li><li><strong>Unexposed Internal Services</strong>: <code>brandhub-ai-service</code> (<code>:8082</code>) has <strong>zero</strong> routes in <code>brandhub-api-gateway</code>; it is reachable solely over the private VPC (<code>brandhub-ai-sg</code>) with <code>X-Internal-Key</code>.</li></ul></li><li><strong>Unified Envelope on Gateway Errors (<code>GlobalErrorWebExceptionHandler</code> + <code>GatewayErrorResponseWriter</code>)</strong>: Serializes <code>401</code>, <code>403</code>, <code>404</code>, <code>429</code>, and <code>503</code> responses in the exact same <code>ApiResponse&lt;T&gt;</code> JSON envelope (<code>success</code>, <code>data</code>, <code>error</code>, <code>requestId</code>, <code>version: &quot;v1&quot;</code>, <code>timestamp</code>) as downstream services, never echoing raw internal Java exception messages on <code>500</code>.</li></ul><hr><h2 id="_5-trade-offs-operational-impact" tabindex="-1">5. Trade-offs &amp; Operational Impact <a class="header-anchor" href="#_5-trade-offs-operational-impact" aria-label="Permalink to &quot;5. Trade-offs &amp; Operational Impact&quot;">​</a></h2><h3 id="positive-outcomes" tabindex="-1">Positive Outcomes <a class="header-anchor" href="#positive-outcomes" aria-label="Permalink to &quot;Positive Outcomes&quot;">​</a></h3><ul><li><strong>Compromise Containment (RS256 Public/Private Split)</strong>: Because <code>brandhub-api-gateway</code> possesses only <code>JWT_PUBLIC_KEY</code>, a compromise of the internet-facing <code>gateway</code> EC2 cannot forge user tokens, decrypt social OAuth tokens, or read private S3 repository files.</li><li><strong>Zero-Trust Defense in Depth</strong>: Stripping <code>X-User-*</code> and <code>X-Internal-Key</code> at <code>InboundSecurityWebFilter</code> <strong>plus</strong> re-verifying the RS256 Bearer token inside <code>business-service</code> prevents privilege escalation even if a misconfigured route ever omits <code>JwtAuthFilter</code>.</li><li><strong>Database-Free Edge Scaling</strong>: Gateway requires only reactive Redis (<code>172.31.24.149:6379</code>) and runs comfortably within <code>640m</code> container memory on a <code>t3.small</code> instance.</li></ul><h3 id="accepted-costs-mitigations" tabindex="-1">Accepted Costs &amp; Mitigations <a class="header-anchor" href="#accepted-costs-mitigations" aria-label="Permalink to &quot;Accepted Costs &amp; Mitigations&quot;">​</a></h3><ul><li><strong>Double RSA Signature Verification</strong>: Both <code>api-gateway</code> and <code>business-service</code> verify the RSA-2048 SHA-256 signature on authenticated requests (~<code>0.1 ms</code> CPU overhead per request — negligible compared to network/DB I/O).</li><li><strong>Burstable <code>t3.small</code> CPU Credits Under Sustained High RPS</strong>: Monitored via CloudWatch <code>CPUCreditBalance</code> and benchmarked with the 60-minute <code>soak</code> profile in <code>prod/loadtest/brandhub-api.k6.js</code>.</li></ul>`,23)])])}const g=t(n,[["render",i]]);export{h as __pageData,g as default};
